 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  texture as tslTexture,
  uniform,
  mix,
  smoothstep,
  length,
  max,
  abs,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  const INK = vec3(22 / 255, 22 / 255, 29 / 255);
  const SURFACE = vec3(11 / 255, 11 / 255, 16 / 255);
  const ACCENT = vec3(1.0, 42 / 255, 56 / 255);

  const WIDTH = 1.6;
  const HEIGHT = 0.48;
  const RADIUS = HEIGHT / 2;

  const uWidth = uniform(WIDTH);
  const uHeight = uniform(HEIGHT);
  const uRadius = uniform(RADIUS);
  const uEdge = uniform(0.05);

  const capHalf = uWidth.div(2).sub(uRadius);

  const st = uv().sub(vec2(0.5, 0.5));
  const q = st.mul(vec2(uWidth, uHeight));
  const d = length(
    max(
      abs(q).sub(vec2(capHalf, 0.0)),
      vec2(0.0, 0.0)
    )
  ).sub(uRadius);

  const alpha = smoothstep(0.0, 0.005, d.mul(-1.0));

  const insideDist = max(d.mul(-1.0), 0.0);
  const edgeMask = smoothstep(uEdge, 0.0, insideDist);

  function buildBadgeColorNodes(tex) {
    const base = tex ? tslTexture(tex, uv()).rgb.mul(INK) : INK;
    const color = mix(base, ACCENT, edgeMask.mul(alpha));
    return { color, alpha };
  }

  const badgeGeo = new PlaneGeometry(WIDTH, HEIGHT, 64, 32);
  const badgeMat = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    side: 2,
  });

  const badge = new Group();
  const badgeMesh = new ctx.THREE.Mesh(badgeGeo, badgeMat);
  badge.add(badgeMesh);
  root.add(badge);

  const bgGeo = new PlaneGeometry(2.4, 1.1, 4, 4);
  const bgMat = new MeshBasicNodeMaterial({ side: 2 });
  const bgGradient = mix(SURFACE, INK, uv().y);
  bgMat.colorNode = bgGradient;
  const bgMesh = new ctx.THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -0.12;
  root.add(bgMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!root.parent && !root.__alive) return;
      const { color } = buildBadgeColorNodes(tex);
      badgeMat.colorNode = color;
      badgeMat.opacityNode = alpha;
      badgeMat.transparent = true;
      badgeMat.needsUpdate = true;
      root.__tex = tex;
    });
  } else {
    const { color } = buildBadgeColorNodes(null);
    badgeMat.colorNode = color;
    badgeMat.opacityNode = alpha;
    badgeMat.needsUpdate = true;
  }

  const primitives = config.cinematicPrimitives || [];
  const effectReturns = [];
  for (const p of primitives) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      effectReturns.push(fn(root, p.params || {}));
    }
  }

  function triggerHover(active) {
    gsap.killTweensOf(root.position);
    gsap.to(root.position, {
      y: active ? 0.15 : 0,
      z: active ? 0.05 : 0,
      duration: active ? 0.35 : 0.45,
      ease: 'power2.out',
    });
  }

  function triggerPress(active) {
    gsap.killTweensOf(root.scale);
    gsap.to(root.scale, {
      x: active ? 0.97 : 1,
      y: active ? 0.97 : 1,
      z: active ? 0.97 : 1,
      duration: active ? 0.12 : 0.25,
      ease: active ? 'back.out(2)' : 'power2.out',
    });
  }

  root.userData.handlers = {
    pointerover: () => triggerHover(true),
    pointerout: () => triggerHover(false),
    pointerdown: () => triggerPress(true),
    pointerup: () => {
      triggerPress(false);
    },
    click: () => {
      ctx.emit('hub-collection.select', { from: config.id });
    },
  };

  root.userData.cleanup = () => {
    root.__alive = false;
    effectReturns.forEach((e) => {
      if (e && e.cleanup) e.cleanup();
    });
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    badgeGeo.dispose();
    badgeMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
    if (root.__tex) root.__tex.dispose();
  };

  return root;
}
